const $=s=>document.querySelector(s),state={topics:new Set(Object.keys(TOPICS)),query:'',view:'map',zoom:1,fit:false,route:false};
let guidePointer=null,guideFrame=0;
function hideCursorGuide(){guidePointer=null;$('#cursor-guide').hidden=true;$('#axis').classList.remove('guide-active');}
function updateCursorGuide(){
 const viewport=$('#map-scroll'),guide=$('#cursor-guide'),axis=$('#axis');
 if(!guidePointer||state.view!=='map'||$('#detail').open){guide.hidden=true;axis.classList.remove('guide-active');return;}
 const rect=viewport.getBoundingClientRect(),x=guidePointer.x-rect.left-viewport.clientLeft,y=guidePointer.y-rect.top-viewport.clientTop;
 if(x<0||x>=viewport.clientWidth||y<0||y>=viewport.clientHeight){guide.hidden=true;axis.classList.remove('guide-active');return;}
 const contentX=x+viewport.scrollLeft;
 guide.style.transform=`translateX(${contentX}px)`;guide.hidden=false;
 axis.style.setProperty('--cursor-x',`${contentX}px`);axis.classList.add('guide-active');
}
function scheduleCursorGuide(){cancelAnimationFrame(guideFrame);guideFrame=requestAnimationFrame(updateCursorGuide);}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=(ids,kind)=>ids.map(id=>ENTITIES[kind][id].title);
const plain=s=>esc(s||'');const prose=s=>`<p>${plain(s)}</p>`;
const route=['ross-plex','sketchpad','simula-i','smalltalk'];
const certainty={supported:'Поддерживается источником',interpretation:'Редакторская интерпретация',disputed:'Спорное утверждение'};
const searchText=e=>[e.title,e.text,...['people','orgs'].flatMap(kind=>e[kind].flatMap(id=>[ENTITIES[kind][id].title,...ENTITIES[kind][id].aliases]))].join(' ').toLocaleLowerCase('ru');
const matches=e=>e.topics.some(t=>state.topics.has(t))&&(!state.route||route.includes(e.id))&&searchText(e).includes(state.query);
const dateLabel=e=>`${e.date.basis==='approximate'?'ок. ':''}${e.date.start}${e.date.end?' — '+e.date.end:''}`;
function openDialog(html){hideCursorGuide();$('#detail-content').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function sourceHTML(key,locator){const [title,url]=SOURCES[key];const target=new URL(url);const time=locator?.match(/\b(\d{1,2}):(\d{2}):(\d{2})\b/);if(time&&['youtube.com','www.youtube.com','youtu.be'].includes(target.hostname))target.searchParams.set('t',String(+time[1]*3600+ +time[2]*60+ +time[3]));return `<a class="source" href="${esc(target.href)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗${locator?'<br>'+esc(locator):''}</a>`;}
function openEvent(id){const e=EVENTS.find(e=>e.id===id);if(!e)return;const links=LINKS.filter(l=>l.from===id||l.to===id);openDialog(`<div class="eyebrow">${esc(dateLabel(e))} / ${e.topics.map(t=>esc(TOPICS[t].name)).join(' · ')}</div><h2>${esc(e.title)}</h2><span class="badge">${e.status==='reviewed'?'Редакционно проверено':'Черновик · требуется редакционная проверка'}</span>${prose(e.text)}<h3>КАКУЮ ПРОБЛЕМУ РЕШАЛИ</h3>${prose(e.problem)}<h3>ЧТО ИЗМЕНИЛОСЬ</h3>${prose(e.meaning)}<h3>ЛЮДИ И ИНСТИТУТЫ</h3><div class="tags">${['people','orgs'].flatMap(kind=>e[kind].map(id=>`<button data-entity="${id}" data-kind="${kind}">${esc(ENTITIES[kind][id].title)}</button>`)).join('')}</div>${e.note?`<p class="note">${esc(e.note)}</p>`:''}${e.more?'<h3>ПОДРОБНЕЕ</h3>'+prose(e.more):''}<h3>СВЯЗИ · ${links.length}</h3>${links.length?links.map(l=>{const other=EVENTS.find(x=>x.id===(l.from===id?l.to:l.from));return `<button class="related" data-event="${other.id}">${l.from===id?'→':'←'} ${esc(dateLabel(other))} · ${esc(other.title)}<span>${esc(l.text)}</span></button><span class="badge">${certainty[l.certainty]} · ${l.status==='reviewed'?'проверено':'черновик'}</span>${l.evidence.map(v=>sourceHTML(v.source,v.locator)).join('')}`;}).join(''):'<p>Связи пока не добавлены. Это не означает их отсутствия.</p>'}<h3>ИСТОЧНИКИ</h3>${e.sources.map(key=>sourceHTML(key)).join('')}`);}
function openEntity(id,kind){const entity=ENTITIES[kind][id];const events=EVENTS.filter(e=>e[kind].includes(id));const body=entity.body.replace(/^# .+\n*/,'');openDialog(`<div class="eyebrow">${kind==='people'?'ЧЕЛОВЕК':'ИНСТИТУТ'}</div><h2>${esc(entity.title)}</h2>${prose(body)}<p>События из выборки атласа. Совместное участие не означает прямого знакомства или сотрудничества.</p>${events.map(e=>`<button class="related" data-event="${e.id}">${esc(dateLabel(e))} · ${esc(e.title)}<span>${esc(names(e.orgs,'orgs').join(' / '))}</span></button>`).join('')}`);}
function setView(view){hideCursorGuide();state.view=view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});render();}
function render(){const events=EVENTS.filter(matches);$('#result-count').textContent=`${events.length} из ${EVENTS.length} событий · ${state.topics.size} линии`;$('#zoom-label').textContent=state.fit?'Обзор':`${Math.round(state.zoom*100)}%`;$('#minus').disabled=!state.fit&&state.zoom<=.5;$('#plus').disabled=!state.fit&&state.zoom>=2;$('#footer-text').textContent=state.route?'Маршрут: два источника идей → Smalltalk':'История не развивается по прямой';$('#map-scroll').hidden=state.view!=='map';$('#directory').hidden=state.view==='map';
if(state.view!=='map'){const ids=new Set(events.flatMap(e=>e[state.view]));$('#directory').innerHTML=[...ids].sort((a,b)=>ENTITIES[state.view][a].title.localeCompare(ENTITIES[state.view][b].title,'ru')).map(id=>{const entity=ENTITIES[state.view][id],ev=events.filter(e=>e[state.view].includes(id));return `<button class="directory-item" data-entity="${id}" data-kind="${state.view}"><strong>${esc(entity.title)}</strong><small>Событий: ${ev.length} · ${Math.min(...ev.map(e=>e.year))}—${Math.max(...ev.map(e=>e.year))}<br>${esc([...new Set(ev.flatMap(e=>names(state.view==='people'?e.orgs:e.people,state.view==='people'?'orgs':'people')))].slice(0,3).join(' / '))}</small></button>`;}).join('')||'<div class="empty">Ничего не найдено. Попробуйте другой запрос.</div>';return;}
const viewport=$('#map-scroll'),minYear=EVENTS.length?Math.floor(Math.min(...EVENTS.map(e=>e.year))/5)*5:1945,maxYear=EVENTS.length?Math.ceil(Math.max(...EVENTS.map(e=>e.date.end?+e.date.end.slice(0,4):e.year))/5)*5:1995,span=Math.max(5,maxYear-minYear),usable=Math.max(240,viewport.clientWidth-205),step=state.fit?usable/span:Math.max(64,usable/span)*state.zoom,width=Math.max(viewport.clientWidth,span*step+205);
const pos={},lanes=[];let y=42;const topicIds=Object.keys(TOPICS).filter(t=>events.some(e=>e.topic===t));const laneShare=Math.max(1,viewport.clientHeight-42)/Math.max(1,topicIds.length);
for(const topic of topicIds){const taken=[];const items=events.filter(e=>e.topic===topic).sort((a,b)=>a.year-b.year||a.id.localeCompare(b.id));const rows=[];for(const e of items){const x=(e.year-minYear)*step+25;let row=0;while(taken[row]!==undefined&&x<taken[row]+177)row++;taken[row]=x;rows.push({e,x,row});}const packedHeight=taken.length*112;const laneHeight=Math.max(laneShare,packedHeight+62);const top=y+38+Math.max(0,(laneHeight-packedHeight-62)/2);for(const {e,x,row}of rows)pos[e.id]={x,y:top+row*112};lanes.push(`<div class="lane-rule" style="top:${y}px"></div><div class="lane" style="top:${y+12}px;color:${TOPICS[topic].color}">${esc(TOPICS[topic].name.toLocaleUpperCase('ru'))}</div>`);y+=laneHeight;}
const height=Math.max(viewport.clientHeight,y);$('#canvas').style.cssText=`width:${width}px;height:${height}px;--grid-height:${height-42}px`;$('#axis').innerHTML=Array.from({length:Math.floor(span/5)+1},(_,i)=>minYear+i*5).map(year=>`<span style="left:${(year-minYear)*step+25}px">${year}</span>`).join('');$('#nodes').innerHTML=lanes.join('')+events.map(e=>`<button class="event" data-event="${e.id}" data-topic="${e.topic}" style="left:${pos[e.id].x}px;top:${pos[e.id].y}px;--event-color:${TOPICS[e.topic].color}"><span class="year">${esc(dateLabel(e))}<span>↗</span></span><strong>${esc(e.title)}</strong><small>${esc(names(e.orgs,'orgs')[0]||'')}</small></button>`).join('')+(events.length?'':'<div class="empty">Ничего не найдено. Измените запрос или сбросьте фильтры.</div>');
$('#time-grid').innerHTML=Array.from({length:Math.floor(span/5)+1},(_,i)=>`<i style="left:${i*5*step+25}px"></i>`).join('');scheduleCursorGuide();
const ids=new Set(events.map(e=>e.id));$('#edges').innerHTML=LINKS.filter(l=>ids.has(l.from)&&ids.has(l.to)).map(l=>{const a=pos[l.from],b=pos[l.to],color=l.type==='people'?'#c5b1f1':TOPICS[EVENTS.find(e=>e.id===l.from).topic].color;const ax=a.x+164,ay=a.y+48,bx=b.x,by=b.y+48;return `<path d="M ${ax} ${ay} C ${ax+45} ${ay},${bx-45} ${by},${bx} ${by}" fill="none" stroke="${color}" stroke-opacity=".5" ${l.type==='idea'?'stroke-dasharray="5 5"':''}/><circle cx="${bx}" cy="${by}" r="2.5" fill="${color}"/>`;}).join('');}
const mapViewport=$('#map-scroll');
mapViewport.addEventListener('pointermove',event=>{if(event.pointerType==='touch'){hideCursorGuide();return;}guidePointer={x:event.clientX,y:event.clientY};scheduleCursorGuide();});
mapViewport.addEventListener('pointerleave',hideCursorGuide);
mapViewport.addEventListener('pointercancel',hideCursorGuide);
mapViewport.addEventListener('scroll',scheduleCursorGuide,{passive:true});
window.addEventListener('blur',hideCursorGuide);
$('#period').textContent=`${Math.min(...EVENTS.map(e=>e.year))} — ${Math.max(...EVENTS.map(e=>e.year))}`;
$('#topics').innerHTML=Object.entries(TOPICS).map(([key,t])=>`<label style="color:${t.color}"><input type="checkbox" value="${key}" checked>${esc(t.name)}<span class="count">${EVENTS.filter(e=>e.topics.includes(key)).length}</span></label>`).join('');
$('#topics').addEventListener('change',e=>{if(e.target.checked)state.topics.add(e.target.value);else state.topics.delete(e.target.value);state.route=false;render();});$('#search').addEventListener('input',e=>{state.query=e.target.value.trim().toLocaleLowerCase('ru');render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
document.addEventListener('click',e=>{const event=e.target.closest('[data-event]');if(event)openEvent(event.dataset.event);const entity=e.target.closest('[data-entity]');if(entity)openEntity(entity.dataset.entity,entity.dataset.kind);});
$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function zoom(delta){state.fit=false;state.zoom=Math.max(.5,Math.min(2,+(state.zoom+delta).toFixed(1)));render();}$('#plus').onclick=()=>zoom(.2);$('#minus').onclick=()=>zoom(-.2);$('#fit').onclick=()=>{state.fit=true;render();$('#map-scroll').scrollLeft=0;};
function reset(){state.query='';state.route=false;state.topics=new Set(Object.keys(TOPICS));$('#search').value='';document.querySelectorAll('#topics input').forEach(i=>i.checked=true);render();}$('#reset').onclick=reset;
function toggleFilters(force){const hidden=force??!$('#filters').hidden;$('#filters').hidden=hidden;$('.workspace').classList.toggle('filters-hidden',hidden);$('#toggle-filters').setAttribute('aria-expanded',String(!hidden));render();}$('#toggle-filters').onclick=()=>toggleFilters();
$('#start').onclick=()=>{reset();state.route=true;state.fit=true;setView('map');$('#map-scroll').scrollLeft=Math.max(0,(1960-Math.floor(Math.min(...EVENTS.map(e=>e.year))/5)*5)*($('#map-scroll').clientWidth-205)/50);if(EVENTS.some(e=>e.id==='sketchpad'))openEvent('sketchpad');};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#fullscreen').title='Полноэкранный режим недоступен. Карта уже занимает всю область страницы.';}};
function method(){openDialog(`<div class="eyebrow">О ПРОЕКТЕ</div><h2>История как передача идей</h2><p>«Нити» — русскоязычная карта истории IT: ${EVENTS.length} событий и ${LINKS.length} связей в текущей выборке.</p><h3>КАК ИССЛЕДОВАТЬ</h3><p>Прокручивайте карту, меняйте масштаб или выберите «Вся история». Нажмите на событие для перехода к людям, институтам и связанным работам. Панель линий можно скрыть кнопкой «Линии».</p><h3>КАК ЧИТАТЬ УТВЕРЖДЕНИЯ</h3><p>Тип связи описывает её характер: развитие технологии, передача идей или переход людей. Отдельная отметка показывает, поддерживается ли утверждение источником, является ли редакторской интерпретацией или остаётся спорным. Черновик ещё не прошёл редакционную проверку.</p><h3>КАК УСТРОЕНА БАЗА</h3><p>Исходные данные хранятся в отдельных Markdown-файлах: события, люди, институты, темы, источники и связи. У записей постоянные ID. Даты имеют точность и основание. Сборщик проверяет ссылки и создаёт данные для карты. Спецификация формата — в docs/CONTENT-SPEC.md в исходниках проекта.</p><p class="note">Исходные 16 событий перенесены со статусом «черновик». Наличие ссылки не заменяет проверку конкретного утверждения. Формулировки задач и значимости — редакционное объяснение. Ранняя линия Plex представлена через Sketchpad и предложения Хоара. Сходство Sketchpad с ECS не считается прямым влиянием на Looking Glass.</p><h3>ИСТОЧНИКИ</h3>${Object.keys(SOURCES).map(k=>sourceHTML(k)).join('')}`);}$('#about').onclick=method;$('#method').onclick=method;
$('#download-data').onclick=e=>{e.preventDefault();const url=URL.createObjectURL(new Blob([JSON.stringify({schema:'niti/export-v1',SOURCES,TOPICS,ENTITIES,EVENTS,LINKS},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='niti-knowledge.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
let resize;new ResizeObserver(()=>{cancelAnimationFrame(resize);resize=requestAnimationFrame(render);}).observe($('.map-area'));
if(matchMedia('(max-width:650px)').matches)toggleFilters(true);else render();
